const emails = $input.all().map(i => i.json);
// Filter: skip automated/noreply/newsletter senders
const skipPatterns = /noreply|no-reply|donotreply|newsletter|notifications?@|alerts?@|mailer@|auto@/i;
const actionable = emails.filter(e => {
  const from = (e.from || '').toLowerCase();
  const subject = (e.subject || '').toLowerCase();
  return !skipPatterns.test(from) && !subject.includes('unsubscribe');
});
if (!actionable.length) {
  return [{ json: { skip: true, message: 'No follow-ups needed today.' } }];
}
const list = actionable.map(e => ({
  id: e.id,
  to: e.to || 'Unknown',
  subject: e.subject || '(no subject)',
  sentDate: e.date,
  snippet: (e.snippet || '').slice(0, 120)
}));
return [{ json: { skip: false, count: list.length, emails: list } }];

