parameters.jsCode:
const aiSummary = $input.first().json.content?.[0]?.text || '';
const data = $('Filter Actionable Emails').first().json;
const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
const emailRows = data.emails.map(e =>
  `<tr><td style="padding:6px 8px">${e.to}</td><td style="padding:6px 8px">${e.subject}</td><td style="padding:6px 8px">${e.sentDate}</td></tr>`
).join('');
const html = `
<h2>⏰ Follow-up Reminder — ${today}</h2>
<p>You have <strong>${data.count} email(s)</strong> awaiting a reply.</p>
<h3>AI Recommendation</h3>
<pre style="font-family:inherit;white-space:pre-wrap;background:#f5f5f5;padding:12px;border-radius:6px">${aiSummary}</pre>
<h3>Full List</h3>
<table border="1" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%">
  <thead style="background:#eee">
    <tr><th style="padding:6px 8px">To</th><th style="padding:6px 8px">Subject</th><th style="padding:6px 8px">Sent</th></tr>
  </thead>
  <tbody>${emailRows}</tbody>
</table>
<hr>
<p style="color:#888;font-size:12px">Generated by Ruflo Email Manager</p>
`;
return [{ json: { subject: `Follow-up Reminder — ${data.count} emails awaiting reply`, html } }];
